"use client";

import {
  Dithering,
  NeuroNoise,
  PerlinNoise,
  SimplexNoise,
  Warp,
} from "@paper-design/shaders-react";
import { type ComponentType, useCallback, useState } from "react";
import {
  continueRender,
  delayRender,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type NoiseFieldVariant =
  | "perlin"
  | "simplex"
  | "neuro"
  | "warp"
  | "dither";

export type NoiseFieldTheme = "light" | "dark";

export interface NoiseFieldProps {
  /** Which noise texture to render. */
  variant?: NoiseFieldVariant;
  /**
   * Color pair preset. Both pairs are deliberately near-invisible so the
   * field reads as texture, not content.
   */
  theme?: NoiseFieldTheme;
  /** Override the theme's background color. */
  colorBack?: string;
  /** Override the theme's texture color. */
  colorFront?: string;
  /** Playback-rate multiplier for the noise drift. */
  speed?: number;
  /**
   * Texture scale. Maps to the natural density knob of each variant
   * (perlin proportion, dither dot size, simplex steps, neuro/warp zoom).
   */
  scale?: number;
  /** Edge softness of the noise features (perlin, simplex, warp). */
  softness?: number;
  /**
   * Feature strength, clamped low by design: neuro contrast and
   * warp distortion/swirl.
   */
  intensity?: number;
  /** Layer opacity — fade the whole field over the backdrop. */
  opacity?: number;
  className?: string;
}

/** snap-cn theme color pairs — hairline-subtle on both canvases. */
export const NOISE_FIELD_THEMES: Record<
  NoiseFieldTheme,
  { colorBack: string; colorFront: string }
> = {
  light: { colorBack: "#FAFAFA", colorFront: "#E4E7EC" },
  dark: { colorBack: "#0A0A0B", colorFront: "#26272B" },
};

/** Upper bound applied to `intensity` so the field never turns loud. */
export const MAX_INTENSITY = 0.5;

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function parseHex(hex: string): [number, number, number] {
  let value = hex.replace("#", "");
  if (value.length === 3) {
    value = value
      .split("")
      .map((c) => c + c)
      .join("");
  }
  const n = Number.parseInt(value.slice(0, 6), 16);
  return [(n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff];
}

/** Linear mix of two hex colors, `t` in [0, 1]. */
export function mixHex(a: string, b: string, t: number): string {
  const pa = parseHex(a);
  const pb = parseHex(b);
  const amount = clamp(t, 0, 1);
  const channels = pa.map((va, i) => Math.round(va + (pb[i] - va) * amount));
  return `#${channels.map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}

/** Theme colors with optional per-prop overrides applied. */
export function resolveColors(
  theme: NoiseFieldTheme,
  colorBack?: string,
  colorFront?: string,
): { colorBack: string; colorFront: string } {
  const base = NOISE_FIELD_THEMES[theme];
  return {
    colorBack: colorBack ?? base.colorBack,
    colorFront: colorFront ?? base.colorFront,
  };
}

export interface NoiseFieldKnobs {
  scale: number;
  softness: number;
  intensity: number;
  colorBack: string;
  colorFront: string;
}

/**
 * Per-variant prop adapter: converts the unified NoiseField knobs into the
 * uniforms of the underlying paper-shaders component.
 */
export function variantShaderProps(
  variant: NoiseFieldVariant,
  knobs: NoiseFieldKnobs,
): Record<string, unknown> {
  const { scale, colorBack, colorFront } = knobs;
  const softness = clamp(knobs.softness, 0, 1);
  const intensity = clamp(knobs.intensity, 0, MAX_INTENSITY);
  const colorMid = mixHex(colorBack, colorFront, 0.5);

  switch (variant) {
    case "perlin":
      return {
        colorBack,
        colorFront,
        proportion: clamp(0.35 * scale, 0.05, 0.9),
        softness,
      };
    case "simplex":
      return {
        colors: [colorBack, colorMid, colorFront],
        stepsPerColor: Math.round(clamp(2 * scale, 1, 6)),
        softness,
      };
    case "neuro":
      return {
        colorBack,
        colorMid,
        colorFront,
        brightness: 0.05,
        contrast: intensity,
        scale: clamp(scale, 0.25, 4),
      };
    case "warp":
      return {
        colors: [colorBack, colorFront, colorBack, colorMid],
        proportion: 0.5,
        softness,
        distortion: intensity,
        swirl: clamp(intensity + 0.1, 0, 0.6),
        scale: clamp(scale, 0.25, 4),
      };
    case "dither":
      return {
        colorBack,
        colorFront,
        shape: "wave",
        type: "4x4",
        size: Math.round(clamp(2 * scale, 1, 8)),
      };
  }
}

const SHADER_BY_VARIANT = {
  perlin: PerlinNoise,
  simplex: SimplexNoise,
  neuro: NeuroNoise,
  warp: Warp,
  dither: Dithering,
} as const;

/**
 * Low-contrast animated noise texture layer. One shared frame-driven
 * wrapper (deterministic — the shader clock is derived from
 * useCurrentFrame) around five paper-shaders noise programs.
 */
export function NoiseField({
  variant = "perlin",
  theme = "light",
  colorBack,
  colorFront,
  speed = 0.4,
  scale = 1,
  softness = 0.5,
  intensity = 0.3,
  opacity = 1,
  className,
}: NoiseFieldProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("noise-field"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  const colors = resolveColors(theme, colorBack, colorFront);
  const Shader = SHADER_BY_VARIANT[variant] as ComponentType<
    Record<string, unknown>
  >;

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0, opacity: clamp(opacity, 0, 1) }}
    >
      <Shader
        speed={0}
        frame={(frame / fps) * speed * 1000}
        fit="cover"
        width={width}
        height={height}
        {...variantShaderProps(variant, {
          scale,
          softness,
          intensity,
          ...colors,
        })}
      />
    </div>
  );
}
